\begin{theorem}[Holder spaces as function spaces]
\label{thm:holder-space-banach}
\uses{def:holder-space}
\dcref{ch5:5.1-thm-1}
\group{Hölder Spaces}

The space of functions $C^{k,\gamma}(\bar U)$ is a Banach space.
\end{theorem}

